import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# &packet.SetHealth{Health: 20}
POSITIVE = bytes.fromhex("28")

# generated by gophertunnel b8bd735:
# &packet.SetHealth{Health: -300}
NEGATIVE = bytes.fromhex("d704")

GOLDENS = [
    pytest.param(v2225.SetHealthPacket(health=20), POSITIVE, id="positive"),
    pytest.param(v2225.SetHealthPacket(health=-300), NEGATIVE, id="negative-is-a-zigzag-varint"),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_health_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_health_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
